finish(HERE, SLUG, cfg, (HERE / "demo_logic.js").read_text("utf-8"), "Webhook FastAPI: roteador de eventos", "Demo interativa de um roteador de webhooks em FastAPI, estilo Make/Zapier, com assinatura, idempotência e retentativa.", ["app.py"])
